// mock/index.ts
// import type { ResType } from '../api/shared';

// 排序选项
export const mockSortOptions = {
  message: 'success',
  data: {
    options: [
      { label: '欢迎度排序', value: 'popular' },
      { label: '好评优先', value: 'score_desc' },
      { label: '低价优先', value: 'price_asc' },
      { label: '高价优先', value: 'price_desc' },
      { label: '距离优先', value: 'distance_asc' },
    ],
  },
};

// 位置选项
export const mockLocationOptions = {
  message: 'success',
  data: {
    options: [
      { label: '不限', value: 'all' },
      { label: '人民广场', value: 'loc_1' },
      { label: '静安寺', value: 'loc_2' },
      { label: '陆家嘴', value: 'loc_3' },
      { label: '迪士尼度假区', value: 'loc_4' },
      { label: '虹桥机场', value: 'loc_5' },
    ],
  },
};

// 价格选项
export const mockPriceOptions = {
  message: 'success',
  data: {
    options: [
      { label: '¥150以下', value: '0-150' },
      { label: '¥150-300', value: '150-300' },
      { label: '¥300-450', value: '300-450' },
      { label: '¥450-600', value: '450-600' },
      { label: '¥600-1000', value: '600-1000' },
      { label: '¥1000以上', value: '1000-99999' },
    ],
  },
};

// 设施选项
export const mockFeatureOptions = {
  message: 'success',
  data: {
    options: [
      { label: '免费取消', value: 'free_cancel' },
      { label: '即时确认', value: 'instant_confirm' },
      { label: '含早餐', value: 'breakfast' },
      { label: '免费停车', value: 'parking' },
      { label: '健身房', value: 'gym' },
      { label: '游泳池', value: 'pool' },
    ],
  },
};

// 酒店列表（分页）
export const mockHotelList = (params?: any) => {
  const { 
    page = 1, 
    pageSize = 10, 
    sort, 
    location, 
    priceRanges = [], 
    features = [],
    city,
    keyword
  } = params || {};
  
  // 创建所有可能的酒店数据
  const allHotels = Array.from({ length: 50 }).map((_, i) => {
    const price = 100 + Math.floor(Math.random() * 1500); // 价格范围100-1600
    const locationTags = ['人民广场', '静安寺', '陆家嘴', '迪士尼度假区', '虹桥机场'];
    const featureTags = ['免费取消', '即时确认', '含早餐', '免费停车', '健身房', '游泳池'];
    
    // 随机分配位置和设施
    const hotelLocation = locationTags[Math.floor(Math.random() * locationTags.length)];
    const hotelFeatures = [];
    // 随机选择1-3个设施
    const featureCount = 1 + Math.floor(Math.random() * 3);
    for (let j = 0; j < featureCount; j++) {
      const randomFeature = featureTags[Math.floor(Math.random() * featureTags.length)];
      if (!hotelFeatures.includes(randomFeature)) {
        hotelFeatures.push(randomFeature);
      }
    }
    
    return {
      id: `hotel_${i}`,
      name: `${['嘉豪', '希尔顿', '万豪', '如家', '汉庭'][Math.floor(Math.random() * 5)]}酒店 ${i + 1}号店`,
      image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=400&q=80',
      score: 3.5 + Math.random() * 1.5,
      comments: Math.floor(Math.random() * 2000) + 100,
      address: `${hotelLocation}附近 | 世纪大道${100 + i}号`,
      tags: hotelFeatures,
      price,
      location: hotelLocation,
    };
  });
  
  // 应用筛选条件
  let filteredHotels = allHotels;
  
  // 位置筛选 - 如果选择了特定位置且不是"不限"
  if (location && location !== 'all') {
    const locationMap: { [key: string]: string } = {
      'loc_1': '人民广场',
      'loc_2': '静安寺',
      'loc_3': '陆家嘴',
      'loc_4': '迪士尼度假区',
      'loc_5': '虹桥机场',
    };
    const locationName = locationMap[location] || location;
    filteredHotels = filteredHotels.filter(hotel => 
      hotel.location.includes(locationName) || hotel.address.includes(locationName)
    );
  }
  
  // 价格区间筛选
  if (priceRanges && priceRanges.length > 0) {
    filteredHotels = filteredHotels.filter(hotel => {
      return priceRanges.some(range => {
        const [min, max] = range.split('-').map(Number);
        if (max === 99999) return hotel.price >= min; // "1000以上"的情况
        return hotel.price >= min && hotel.price <= max;
      });
    });
  }
  
  // 设施筛选
  if (features && features.length > 0) {
    const featureMap: { [key: string]: string } = {
      'free_cancel': '免费取消',
      'instant_confirm': '即时确认',
      'breakfast': '含早餐',
      'parking': '免费停车',
      'gym': '健身房',
      'pool': '游泳池',
    };
    
    filteredHotels = filteredHotels.filter(hotel => {
      // 只要酒店包含任一选中的设施即可
      return features.some(feature => {
        const featureName = featureMap[feature] || feature;
        return hotel.tags.includes(featureName);
      });
    });
  }
  
  // 关键词搜索
  if (keyword) {
    filteredHotels = filteredHotels.filter(hotel => 
      hotel.name.includes(keyword) || 
      hotel.address.includes(keyword)
    );
  }
  
  // 如果没有筛选结果，返回所有酒店（放宽条件）
  if (filteredHotels.length === 0) {
    filteredHotels = allHotels;
  }
  
  // 排序
  if (sort) {
    switch (sort) {
      case 'price_asc':
        filteredHotels.sort((a, b) => a.price - b.price);
        break;
      case 'price_desc':
        filteredHotels.sort((a, b) => b.price - a.price);
        break;
      case 'score_desc':
        filteredHotels.sort((a, b) => b.score - a.score);
        break;
      case 'distance_asc':
        // 这里简化处理，随机排序
        filteredHotels.sort(() => Math.random() - 0.5);
        break;
      default:
        // 默认按欢迎度排序（随机）
        filteredHotels.sort(() => Math.random() - 0.5);
    }
  }
  
  // 分页处理
  const total = filteredHotels.length;
  const startIndex = (page - 1) * pageSize;
  const endIndex = startIndex + pageSize;
  const list = filteredHotels.slice(startIndex, endIndex);
  const hasMore = endIndex < total;
  
  return {
    message: 'success',
    data: {
      list,
      total,
      page,
      pageSize,
      hasMore,
    },
  };
};
